import SwiftUI
import Supabase

// MARK: - Goal Completion Model

// A permanent snapshot of a completed goal from Supabase.
nonisolated struct GoalCompletion: Decodable, Identifiable {

    let id: UUID
    let goal_type: String
    let starting_value: Double
    let target_value: Double
    let completed_value: Double
    let unit: String
    let activity_date: String?
    let completed_at: String

    var title: String {

        switch goal_type {

        case "lose_weight":
            return "Lose Weight"

        case "gain_weight":
            return "Gain Weight"

        case "increase_steps":
            return "Daily Step Goal"

        default:
            return goal_type
        }
    }
}


// MARK: - Goal History View

struct GoalHistoryView: View {

    // Stores completed goals retrieved from Supabase
    @State private var completions: [GoalCompletion] = []

    // Controls the loading indicator
    @State private var isLoading = true

    // Stores any errors encountered
    @State private var errorMessage: String?


    // MARK: - Filter Weight Goals

    private var weightGoals: [GoalCompletion] {

        completions.filter {
            $0.unit == "lbs"
        }
    }


    // MARK: - Filter Step Goals

    private var stepGoals: [GoalCompletion] {

        completions.filter {
            $0.unit == "steps"
        }
    }


    // MARK: - Main View

    var body: some View {

        ScrollView {

            VStack(alignment: .leading, spacing: 20) {

                // MARK: - Loading State

                if isLoading {

                    ProgressView("Loading goal history...")
                        .frame(maxWidth: .infinity)


                // MARK: - Error State

                } else if let errorMessage {

                    VStack(spacing: 12) {

                        Text(errorMessage)
                            .foregroundStyle(.secondary)

                        Button("Retry") {

                            Task {

                                await loadHistory()
                            }
                        }
                    }
                    .frame(maxWidth: .infinity)


                // MARK: - Empty History

                } else if completions.isEmpty {

                    ContentUnavailableView(

                        "No Completed Goals Yet",

                        systemImage: "target",

                        description: Text(
                            "Your completed goals will appear here as you reach them."
                        )
                    )


                } else {

                    // MARK: - Completed Goal Summary

                    HStack {

                        summary(
                            title: "Weight Goals",
                            count: weightGoals.count
                        )

                        summary(
                            title: "Step Goal Days",
                            count: stepGoals.count
                        )
                    }


                    // MARK: - Completed Weight Goals

                    if !weightGoals.isEmpty {

                        Text("Weight Goals")
                            .font(.title3.bold())

                        ForEach(weightGoals) { completion in

                            completionCard(completion)
                        }
                    }


                    // MARK: - Completed Daily Step Goals

                    if !stepGoals.isEmpty {

                        Text("Daily Step Goals")
                            .font(.title3.bold())

                        ForEach(stepGoals) { completion in

                            completionCard(completion)
                        }
                    }
                }
            }
            .padding()

        } // Closes ScrollView

        .background(
            Color(.systemGroupedBackground)
        )

        .navigationTitle("Goal History")
        .navigationBarTitleDisplayMode(.inline)


        // MARK: - Initial Loading

        .task {

            await loadHistory()
        }


        // MARK: - Pull to Refresh

        .refreshable {

            await loadHistory()
        }

    } // Closes body


    // MARK: - Summary Card

    private func summary(
        title: String,
        count: Int
    ) -> some View {

        VStack(alignment: .leading, spacing: 6) {

            Text(title)
                .font(.caption)
                .foregroundStyle(.secondary)

            Text(count.formatted())
                .font(.title.bold())
                .foregroundStyle(.green)
        }

        .frame(
            maxWidth: .infinity,
            alignment: .leading
        )

        .padding()

        .background(
            Color(.secondarySystemGroupedBackground)
        )

        .cornerRadius(16)
    }


    // MARK: - Completed Goal Card

    private func completionCard(
        _ goal: GoalCompletion
    ) -> some View {

        VStack(alignment: .leading, spacing: 12) {

            // MARK: Goal Information

            HStack {

                Image(
                    systemName: goal.unit == "steps"
                    ? "figure.walk"
                    : "scalemass.fill"
                )
                .foregroundStyle(.green)
                .font(.title2)


                VStack(alignment: .leading, spacing: 4) {

                    Text(goal.title)
                        .font(.headline)

                    Text(completionDate(goal))
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }

                Spacer()

                Image(systemName: "checkmark.seal.fill")
                    .foregroundStyle(.green)
                    .font(.title2)
            }

            Divider()


            // MARK: Starting Value

            // Only weight goals need to display
            // the starting value.

            if goal.unit == "lbs" {

                valueRow(
                    "Starting",
                    goal.starting_value,
                    goal.unit
                )
            }


            // MARK: Target Value

            valueRow(
                "Target",
                goal.target_value,
                goal.unit
            )


            // MARK: Completion Value

            valueRow(
                "Recorded at completion",
                goal.completed_value,
                goal.unit
            )


            // MARK: Completed Progress Bar

            ProgressView(value: 1.0)
                .tint(.green)


            // MARK: Completion Status

            Label(
                "Completed",
                systemImage: "checkmark.circle.fill"
            )
            .font(.caption)
            .foregroundStyle(.green)
        }

        .padding()

        .frame(
            maxWidth: .infinity,
            alignment: .leading
        )

        .background(
            Color(.secondarySystemGroupedBackground)
        )

        .cornerRadius(16)
    }


    // MARK: - Goal Value Row

    // Displays a title and its corresponding value.
    //
    // Example:
    // Starting                 190 lbs
    // Target                   180 lbs

    private func valueRow(
        _ title: String,
        _ value: Double,
        _ unit: String
    ) -> some View {

        HStack {

            Text(title)
                .foregroundStyle(.secondary)

            Spacer()

            Text(
                "\(value.formatted(.number.precision(.fractionLength(0...2)))) \(unit)"
            )
            .fontWeight(.semibold)
        }
        .font(.subheadline)
    }


    // MARK: - Format Completion Date

    private func completionDate(
        _ goal: GoalCompletion
    ) -> String {

        // Daily step goals use the activity date.

        if let day = goal.activity_date {

            let formatter = DateFormatter()

            formatter.locale = Locale(
                identifier: "en_US_POSIX"
            )

            formatter.timeZone = TimeZone(
                secondsFromGMT: 0
            )

            formatter.dateFormat = "yyyy-MM-dd"

            if let date = formatter.date(from: day) {

                formatter.dateStyle = .medium
                formatter.timeStyle = .none

                return formatter.string(from: date)
            }

            return day
        }


        // Weight goals use the completion timestamp.

        let formatter = ISO8601DateFormatter()

        formatter.formatOptions = [
            .withInternetDateTime,
            .withFractionalSeconds
        ]

        if let date = formatter.date(
            from: goal.completed_at
        ) {

            return date.formatted(
                date: .abbreviated,
                time: .omitted
            )
        }


        // Try again without fractional seconds.

        formatter.formatOptions = [
            .withInternetDateTime
        ]

        return formatter.date(
            from: goal.completed_at
        )?.formatted(
            date: .abbreviated,
            time: .omitted
        ) ?? goal.completed_at
    }


    // MARK: - Load Goal History From Supabase

    @MainActor
    private func loadHistory() async {

        // Start loading and clear previous errors
        isLoading = true
        errorMessage = nil

        // Stop loading when the function finishes
        defer {

            isLoading = false
        }


        // Make sure the user is signed in

        guard let userID =
                supabase.auth.currentUser?.id else {

            completions = []

            errorMessage =
                "Sign in to view your goal history."

            return
        }


        do {

            // Retrieve completed goals belonging
            // to the currently signed-in user.

            let rows: [GoalCompletion] = try await supabase

                .from("goal_completions")

                .select("""
                    id,
                    goal_type,
                    starting_value,
                    target_value,
                    completed_value,
                    unit,
                    activity_date,
                    completed_at
                    """)

                .eq(
                    "user_id",
                    value: userID.uuidString
                )

                .order(
                    "completed_at",
                    ascending: false
                )

                .order(
                    "id",
                    ascending: false
                )

                .execute()
                .value


            // Check whether the request was cancelled.

            try Task.checkCancellation()


            // Make sure the same user is still signed in.

            guard supabase.auth.currentUser?.id
                    == userID else {

                completions = []

                return
            }


            // Update the Goal History interface.

            completions = rows


        } catch is CancellationError {

            return


        } catch {

            errorMessage =
                "Could not load goal history. Please try again."

            print(
                "Goal history error: \(error.localizedDescription)"
            )
        }
    }

} // Closes GoalHistoryView
